"""Freeze a development-only branch and small MIT reference source dependency."""
from pathlib import Path
import json,hashlib,urllib.request,subprocess
P=Path(__file__).parent;ROOT=P.parents[1];OLD=ROOT/'experiments/oulad_dynamic_20261019_01'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,z):(P/n).write_text(json.dumps(z,ensure_ascii=False,indent=2),encoding='utf8')
if (P/'protocol.json').exists():raise RuntimeError('no overwrite')
