pres={str(p.relative_to(ROOT)).replace('\\','/'):sha(p) for p in inputs};save('preservation.json',pres)
# Read back the exact prior reports from the already available research-sync checkout.
sync=ROOT/'.tmp/research-sync-strong-20261019-01';checks=[]
for folder,name,local in [('2026-10-19-oulad-dynamic-01','mmfopd_oulad_report.md',OLD/'mmfopd_oulad_report.md'),('2026-10-19-mmfopd-projection-diagnosis-01','mmfopd_projection_diagnosis.md',ROOT/'experiments/mmfopd_projection_diagnosis_20261019_01/mmfopd_projection_diagnosis.md')]:
 result=subprocess.run(['git','show','origin/main:CG/experiments/'+folder+'/'+name],cwd=sync,capture_output=True,check=True);digest=hashlib.sha256(result.stdout).hexdigest();assert digest==sha(local);checks.append({'path':'CG/experiments/'+folder+'/'+name,'matches_local':True,'sha256':digest})
save('prior_remote_readback.json',checks)
base='https://raw.githubusercontent.com/EleutherAI/concept-erasure/main/';vendor=P/'vendor/concept_erasure';vendor.mkdir(parents=True,exist_ok=True);total=0;refs=[]
for name in ['leace.py','caching.py','shrinkage.py','utils.py']:
 url=base+'concept_erasure/'+name
 try:
  data=urllib.request.urlopen(url,timeout=30).read(65537);assert len(data)<=65536
 except urllib.error.HTTPError as exc:
  if name=='utils.py' and exc.code==404:continue
  raise
 total+=len(data);assert total<128*1024;(vendor/name).write_bytes(data);refs.append({'url':url,'bytes':len(data),'sha256':sha(vendor/name)})
data=urllib.request.urlopen(base+'LICENSE',timeout=30).read(16384);(P/'vendor/LICENSE-concept-erasure').write_bytes(data);(vendor/'__init__.py').write_text('from .leace import LeaceFitter, LeaceEraser\n',encoding='utf8');save('reference_sources.json',{'references':refs,'license':'MIT, Copyright2023 EleutherAI, full notice included','download_bytes_small_source_only':total+len(data),'data_or_models_downloaded':False,'official_LEACE_options':{'affine':True,'shrinkage':False,'constrain_cov_trace':False,'svd_tol':1e-10}})
plan={'status':'FROZEN_BEFORE_NEW_REPRESENTATION_OR_PROJECTION_FIT','classification':'DEVELOPMENT_EXPLORATORY','seed':20261020,'input':'existing2013J train484/dev166 students,1337/473 snapshots only; no2014J access','contexts':'all3 frozen intents xexplicit/ambiguous, original task definitions and public context unchanged','representation':'26 coordinates:13 numeric safe values median-imputed using train medians +13 missing indicators; every coordinate centered/scaled with train statistics; all field names/types are fixed public schema; no sensitive columns, student IDs, future labels or public module/cutoff in z','protected':['gender_F','disability_Y'],'OPP':'orthonormal left singular vectors U of train cross-covariance C=Cov(z,s); P=I-UU.T. Public official LEACE(method=orth) parity checked. Not a new erasure algorithm.','attention':'task-only existing TFIDF cosine on common metadata; picks3 value-coordinate readout slots, no sensitivity/role reward in task utility','no_attention':'fixed train-only MI top3 slots(latest_score,inactive_days,clicks_recent), same all contexts; not random/weak truncation','factorial_summary_methods':['Att+Identity','NoAtt+OPP','Att+OPP','NoAtt+Identity'],'references':['Att+INLP3','Att+LEACE'],'field_anchors':['B0 SafeTaskTopK','B1 legacy Repaired-Full','B2 FIELD legacy no-role-projection','TaskSlot'],'field_anchors_protocol':'reuse existing exactly same cohort/model fits with provenance, not refit or assign new projection credit','INLP':'faithful train-only autoregressive intersection-nullspace algorithm;3 iterations LinearSVC C1 balanced max_iter20000 on four joint sensitive classes; accept all iterations, no dev tuning or stopping by dev AUC','LEACE':'official vendored MIT implementation, float64, affine, no shrinkage/trace constraint, tol1e-10; generally oblique, not called Euclidean orthogonal','output_interface_A':'three finite numeric coordinates c0..c2 of zP or zL, task-dependent readout Q; round3 decimal places, serialize c0=... etc and parse actual wire; cap64 real Qwen tokens, no padding. No raw identity/label/predicted attribute output.','budget_caveat':'summary has3 scalars but may mix all13 safe fields; same64-token cap and safe source pool, not equivalent toK3 raw-field information budget. Compare factorial causally only within summary interface.','interface_B':'not implemented: no calibrated mapping from orthogonal coordinate erasure to safe field/granularity risk, do not invent it','predictor':'same Ridge alpha10,train-only DictVectorizer/StandardScaler,clip0..100, same next scheduled TMA target as old benchmark','attackers':'same fixed LR C1 balanced and RF64 depth6 minleaf5 balanced_subsample, seed20261020; train only; separate internal(z only,z+public) and actual parsed release+public attacks; public-only calibration; no posthoc attacker weakening','metrics':'per protected attribute BA/AUC/Accuracy, signed augmentation-public deltas and nonnegative observed excess; utilityMAE, observed-gradeMAE, real replyToken, source-slot contractRecall and missing fraction; actual fact recall NA for mixed summaries','projection_math':'check U.TU, P symmetry/idempotence/U residual, train crosscovariance, total and readout distortions; residual nonlinear/background leakage explicitly measured','mechanism_gate':'phaseC not run automatically. Only if Att+OPP changes actual payloads, improves LR AUC by>=.02 for at least one attribute withoutRF AUC worsening>.02, and MAE increases no more than2 points vs same-interface Att+Identity in>=1 frozen context. This is a development screening gate, not proof. No tuning if false. If true freeze unchanged candidates and request fresh independent validation; old2014J is used, never blind.','max_new_projection_fits':'one covariance projector, one official LEACE, one official-orth parity fit,3 INLP classifiers; no search','paid_calls':0,'large_downloads':False,'core_or_old_results_edits':False}
save('protocol.json',plan);print(json.dumps({'status':'FROZEN_DEV_ONLY','small_reference_source_bytes':total,'prior_reports_verified':len(checks)},indent=2))
